function firstToArrive(a: number, b: number, c: number): number {
  while (true) {
    if (a === c && b === c) return 0;
    if (a === c) return 1;
    if (b === c) return 2;
    a += Math.sign(c - a);
    b += Math.sign(c - b);
  }
}

